/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0d0d0f;
  --bg-secondary: #141418;
  --bg-card: #1a1a20;
  --bg-elevated: #22222a;
  --border: #2a2a35;
  --border-light: #38384a;
  --accent: #c9a84c;
  --accent-hover: #e0bc65;
  --accent-muted: rgba(201,168,76,.15);
  --text-primary: #f0efea;
  --text-secondary: #9d9d9d;
  --text-muted: #5a5a6a;
  --red: #e05252;
  --green: #52c27a;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,.5);
  --shadow-hover: 0 8px 40px rgba(0,0,0,.7);
  --transition: 0.22s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'Segoe UI', system-ui, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
ul { list-style: none; }

/* ===== TYPOGRAPHY ===== */
.label {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
}

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #000;
  padding: .5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 700;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== NAV ===== */
nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.9);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 64px;
}

.nav-logo {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--text-primary);
  flex-shrink: 0;
}
.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex;
  gap: .25rem;
}
.nav-links a {
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a:focus-visible {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.nav-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: .75rem;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: .5rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: .4rem .75rem;
  transition: border-color var(--transition);
}
.nav-search:focus-within { border-color: var(--accent); }
.nav-search input {
  background: none;
  border: none;
  outline: none;
  color: var(--text-primary);
  font-size: .875rem;
  width: 180px;
}
.nav-search input::placeholder { color: var(--text-muted); }
.nav-search svg { color: var(--text-muted); flex-shrink: 0; }

.btn-icon {
  position: relative;
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  transition: color var(--transition), border-color var(--transition);
}
.btn-icon:hover,
.btn-icon:focus-visible {
  color: var(--text-primary);
  border-color: var(--border-light);
}
.btn-icon .badge {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--accent);
  color: #000;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  pointer-events: none;
}

.nav-menu-toggle {
  display: none;
  width: 40px; height: 40px;
  align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
}

/* ===== MAIN CONTAINER ===== */
main { max-width: 1280px; margin: 0 auto; padding: 0 1.5rem; }

section { padding: 5rem 0; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2.5rem;
  gap: 1rem;
}
.section-header-left { display: flex; flex-direction: column; gap: .4rem; }
.section-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -.02em;
}
.btn-link {
  font-size: .875rem;
  color: var(--accent);
  display: flex; align-items: center; gap: .3rem;
  transition: gap var(--transition);
  white-space: nowrap;
}
.btn-link:hover { gap: .55rem; }
.btn-link svg { transition: transform var(--transition); }
.btn-link:hover svg { transform: translateX(3px); }

/* ===== HERO ===== */
.hero {
  padding: 2rem 0 5rem;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 1.5rem;
  align-items: stretch;
}

.hero-main {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-secondary);
  min-height: 520px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  border: 1px solid var(--border);
}

.hero-main-img {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a1020 0%, #0d1a2a 50%, #1a1510 100%);
  overflow: hidden;
}
.hero-main-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(13,13,15,.95) 0%, rgba(13,13,15,.3) 55%, transparent 100%);
}

/* Decorative geometric shapes in hero */
.hero-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: .35;
}
.hero-shape-1 {
  width: 350px; height: 350px;
  background: radial-gradient(circle, #c9a84c, transparent);
  top: -80px; right: 80px;
}
.hero-shape-2 {
  width: 250px; height: 250px;
  background: radial-gradient(circle, #5265c9, transparent);
  bottom: 80px; left: 60px;
}
.hero-shape-3 {
  width: 200px; height: 200px;
  background: radial-gradient(circle, #c95282, transparent);
  top: 120px; left: 30%;
}

.hero-main-content {
  position: relative;
  z-index: 1;
  padding: 2.5rem;
}
.hero-main-content .label { margin-bottom: .75rem; }
.hero-main-content h1 {
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
  margin-bottom: 1rem;
}
.hero-main-content p {
  color: var(--text-secondary);
  max-width: 440px;
  margin-bottom: 1.75rem;
  font-size: 1.05rem;
}
.hero-ctas { display: flex; gap: .75rem; flex-wrap: wrap; }

.hero-sidebar { display: flex; flex-direction: column; gap: 1.5rem; }

.hero-card {
  flex: 1;
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 220px;
  transition: border-color var(--transition), transform var(--transition);
}
.hero-card:hover { border-color: var(--border-light); transform: translateY(-2px); }
.hero-card:focus-within { border-color: var(--accent); }

.hero-card-bg {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.hero-card-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(13,13,15,.9) 0%, rgba(13,13,15,.2) 60%, transparent 100%);
}

.hero-card-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
  opacity: .4;
}
.hero-card-1 .hero-card-bg { background: linear-gradient(135deg, #1a2010, #0d1520); }
.hero-card-1 .hero-card-shape { width: 180px; height: 180px; background: radial-gradient(circle, #52c27a, transparent); top: -20px; right: -20px; }
.hero-card-2 .hero-card-bg { background: linear-gradient(135deg, #1a1020, #2a1510); }
.hero-card-2 .hero-card-shape { width: 180px; height: 180px; background: radial-gradient(circle, #e05252, transparent); top: -20px; right: -20px; }

.hero-card-content {
  position: relative;
  z-index: 1;
  padding: 1.5rem;
}
.hero-card-content .label { margin-bottom: .5rem; }
.hero-card-content h2 {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: .5rem;
}
.hero-card-content p {
  font-size: .875rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .65rem 1.4rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--accent);
  color: #0d0d0f;
}
.btn-primary:hover {
  background: var(--accent-hover);
  box-shadow: 0 0 24px rgba(201,168,76,.35);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1px solid var(--border-light);
}
.btn-secondary:hover {
  background: var(--bg-card);
  border-color: var(--accent);
  color: var(--accent);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  padding: .5rem 1rem;
  font-size: .825rem;
}
.btn-ghost:hover {
  color: var(--text-primary);
  border-color: var(--border-light);
}

.btn-sm {
  padding: .4rem 1rem;
  font-size: .8rem;
}

/* ===== PRODUCT CARDS ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  position: relative;
}
.product-card:hover {
  border-color: var(--border-light);
  box-shadow: var(--shadow-hover);
  transform: translateY(-3px);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-elevated);
  overflow: hidden;
}
.product-img-placeholder {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
}
.product-badge {
  position: absolute;
  top: .75rem; left: .75rem;
  padding: .25rem .6rem;
  border-radius: var(--radius-sm);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.badge-new { background: var(--accent); color: #000; }
.badge-sale { background: var(--red); color: #fff; }
.badge-hot { background: #e07a52; color: #fff; }

.product-wishlist {
  position: absolute;
  top: .75rem; right: .75rem;
  width: 32px; height: 32px;
  background: rgba(13,13,15,.7);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--text-muted);
  transition: color var(--transition), background var(--transition);
}
.product-wishlist:hover,
.product-wishlist.active { color: var(--red); background: rgba(224,82,82,.15); }
.product-wishlist:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.product-info {
  padding: 1rem 1rem .75rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.product-category {
  font-size: .7rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: .3rem;
}
.product-name {
  font-size: .95rem;
  font-weight: 600;
  margin-bottom: .5rem;
  color: var(--text-primary);
  line-height: 1.4;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  margin-bottom: auto;
  padding-bottom: .75rem;
}
.stars { color: var(--accent); font-size: .8rem; letter-spacing: -.05em; }
.rating-count { font-size: .75rem; color: var(--text-muted); }
.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
  padding-top: .75rem;
  border-top: 1px solid var(--border);
  margin-top: .5rem;
}
.product-price { display: flex; align-items: baseline; gap: .4rem; }
.price-current { font-size: 1.1rem; font-weight: 700; color: var(--text-primary); }
.price-original {
  font-size: .8rem;
  color: var(--text-muted);
  text-decoration: line-through;
}
.price-save {
  font-size: .7rem;
  color: var(--green);
  font-weight: 600;
}
.btn-add-cart {
  width: 36px; height: 36px;
  flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: var(--accent-muted);
  border: 1px solid rgba(201,168,76,.3);
  border-radius: var(--radius-sm);
  color: var(--accent);
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
}
.btn-add-cart:hover {
  background: var(--accent);
  color: #000;
}
.btn-add-cart:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.btn-add-cart:active { transform: scale(.92); }

/* ===== DEALS SECTION ===== */
.deals-section { background: var(--bg-secondary); border-radius: var(--radius-lg); padding: 3.5rem; margin: 0 0 5rem; }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  transition: border-color var(--transition), transform var(--transition);
  position: relative;
  overflow: hidden;
}
.deal-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 3px; height: 100%;
  background: var(--accent);
  opacity: 0;
  transition: opacity var(--transition);
}
.deal-card:hover { border-color: var(--border-light); transform: translateX(3px); }
.deal-card:hover::before { opacity: 1; }

.deal-thumb {
  width: 72px; height: 72px;
  flex-shrink: 0;
  background: var(--bg-elevated);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  font-size: 2rem;
}
.deal-info { flex: 1; min-width: 0; }
.deal-name {
  font-size: .9rem;
  font-weight: 600;
  margin-bottom: .25rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.deal-desc { font-size: .78rem; color: var(--text-muted); margin-bottom: .6rem; }
.deal-price { display: flex; align-items: baseline; gap: .4rem; margin-bottom: .75rem; }
.deal-current { font-size: 1.1rem; font-weight: 700; color: var(--accent); }
.deal-original { font-size: .8rem; color: var(--text-muted); text-decoration: line-through; }
.deal-off { font-size: .7rem; background: rgba(224,82,82,.2); color: var(--red); padding: .1rem .4rem; border-radius: 3px; font-weight: 600; }

.deal-progress { margin-bottom: .75rem; }
.progress-label {
  display: flex; justify-content: space-between;
  font-size: .7rem; color: var(--text-muted); margin-bottom: .3rem;
}
.progress-bar {
  height: 4px;
  background: var(--bg-elevated);
  border-radius: 99px;
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-hover));
  border-radius: 99px;
  transition: width .6s cubic-bezier(.4,0,.2,1);
}

.deal-countdown {
  display: flex;
  gap: .35rem;
  margin-bottom: .75rem;
}
.countdown-block {
  background: var(--bg-elevated);
  border-radius: 4px;
  padding: .2rem .4rem;
  text-align: center;
  min-width: 36px;
}
.countdown-num {
  display: block;
  font-size: .95rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}
.countdown-lbl { font-size: .55rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: .05em; }
.countdown-sep { color: var(--text-muted); font-weight: 700; padding-top: .1rem; font-size: .9rem; }

/* ===== CATEGORIES STRIP ===== */
.categories-strip {
  padding: 0 0 5rem;
}

.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.category-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .65rem;
  padding: 1.5rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  cursor: pointer;
  color: var(--text-secondary);
}
.category-pill:hover,
.category-pill:focus-visible {
  border-color: var(--accent);
  background: var(--accent-muted);
  color: var(--accent);
  transform: translateY(-3px);
  outline: none;
}
.category-icon { font-size: 1.8rem; }
.category-name { font-size: .78rem; font-weight: 600; text-align: center; }

/* ===== EDITORIAL ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}

.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.editorial-card:hover { border-color: var(--border-light); transform: translateY(-2px); }
.editorial-card:focus-within { border-color: var(--accent); }

.editorial-card-featured { grid-row: 1 / 3; }

.editorial-img {
  position: relative;
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--bg-elevated);
  flex-shrink: 0;
}
.editorial-card-featured .editorial-img { aspect-ratio: auto; flex: 1; }

.editorial-img-bg {
  width: 100%; height: 100%;
}
.editorial-img-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(13,13,15,.7) 0%, transparent 60%);
}

.ed-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(50px);
  opacity: .3;
}
.ed-featured-bg { background: linear-gradient(135deg, #1a1020, #0d1a1a); }
.ed-featured-s1 { width: 300px; height: 300px; background: radial-gradient(circle, #c9a84c, transparent); top: 20%; left: 20%; }
.ed-featured-s2 { width: 200px; height: 200px; background: radial-gradient(circle, #5282e0, transparent); bottom: 10%; right: 15%; }
.ed-sm-1 { background: linear-gradient(135deg, #101a20, #1a1020); }
.ed-sm-1-s { width: 200px; height: 200px; background: radial-gradient(circle, #52c2c2, transparent); top: -20%; right: -10%; }
.ed-sm-2 { background: linear-gradient(135deg, #201010, #1a1a10); }
.ed-sm-2-s { width: 200px; height: 200px; background: radial-gradient(circle, #e07a52, transparent); top: -20%; left: -10%; }

.editorial-body {
  padding: 1.5rem;
  flex-shrink: 0;
}
.editorial-card-featured .editorial-body { padding: 1.75rem 2rem; }
.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  margin-bottom: .75rem;
}
.editorial-tag {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  background: var(--accent-muted);
  color: var(--accent);
  border-radius: 3px;
}
.editorial-date { font-size: .75rem; color: var(--text-muted); }
.editorial-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: .5rem;
}
.editorial-card-featured .editorial-title { font-size: 1.4rem; margin-bottom: .75rem; }
.editorial-excerpt { font-size: .85rem; color: var(--text-secondary); line-height: 1.6; }
.editorial-card-featured .editorial-excerpt { margin-bottom: 1.25rem; }
.editorial-read-more {
  font-size: .85rem;
  color: var(--accent);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  transition: gap var(--transition);
}
.editorial-read-more:hover { gap: .55rem; }

/* ===== BANNER STRIP ===== */
.promo-banner {
  background: linear-gradient(135deg, #1a140a, #0d1520);
  border: 1px solid rgba(201,168,76,.25);
  border-radius: var(--radius-lg);
  padding: 2.5rem 3rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: 5rem;
  position: relative;
  overflow: hidden;
}
.promo-banner::before {
  content: '';
  position: absolute;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(201,168,76,.12), transparent);
  right: -100px; top: -150px;
  border-radius: 50%;
  pointer-events: none;
}
.promo-banner-text { position: relative; z-index: 1; }
.promo-banner-text .label { margin-bottom: .5rem; }
.promo-banner-text h2 { font-size: 1.6rem; font-weight: 800; letter-spacing: -.02em; }
.promo-banner-text p { color: var(--text-secondary); margin-top: .35rem; }
.promo-banner-actions { position: relative; z-index: 1; display: flex; gap: .75rem; flex-shrink: 0; }

/* ===== TESTIMONIALS ===== */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}

.testimonial-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1.75rem;
}
.testimonial-stars { color: var(--accent); font-size: .9rem; letter-spacing: -.05em; margin-bottom: 1rem; }
.testimonial-text {
  font-size: .9rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 1.25rem;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: .75rem; }
.testimonial-avatar {
  width: 38px; height: 38px;
  border-radius: 50%;
  background: var(--bg-elevated);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  border: 2px solid var(--border-light);
}
.testimonial-name { font-size: .875rem; font-weight: 600; }
.testimonial-handle { font-size: .75rem; color: var(--text-muted); }

/* ===== FOOTER ===== */
footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  margin-top: 5rem;
}

.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 4rem 1.5rem 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand .nav-logo { margin-bottom: .75rem; font-size: 1.5rem; }
.footer-brand p { font-size: .875rem; color: var(--text-muted); max-width: 240px; line-height: 1.7; margin-bottom: 1.5rem; }
.footer-socials { display: flex; gap: .5rem; }
.footer-social {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  font-size: .9rem;
  transition: color var(--transition), border-color var(--transition);
}
.footer-social:hover,
.footer-social:focus-visible {
  color: var(--accent);
  border-color: var(--accent);
}

.footer-col h3 { font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--text-secondary); margin-bottom: 1rem; }
.footer-col ul { display: flex; flex-direction: column; gap: .5rem; }
.footer-col ul a {
  font-size: .875rem;
  color: var(--text-muted);
  transition: color var(--transition);
}
.footer-col ul a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.footer-bottom p { font-size: .8rem; color: var(--text-muted); }
.footer-bottom-links { display: flex; gap: 1.5rem; }
.footer-bottom-links a { font-size: .8rem; color: var(--text-muted); transition: color var(--transition); }
.footer-bottom-links a:hover { color: var(--text-primary); }

/* ===== CART TOAST ===== */
.cart-toast {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  background: var(--bg-elevated);
  border: 1px solid var(--accent);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
  display: flex;
  align-items: center;
  gap: .75rem;
  box-shadow: var(--shadow);
  z-index: 200;
  transform: translateY(120%);
  opacity: 0;
  transition: transform .3s cubic-bezier(.4,0,.2,1), opacity .3s;
  pointer-events: none;
  max-width: 320px;
}
.cart-toast.show { transform: translateY(0); opacity: 1; pointer-events: auto; }
.cart-toast-icon { font-size: 1.4rem; flex-shrink: 0; }
.cart-toast-text { font-size: .875rem; font-weight: 600; }
.cart-toast-sub { font-size: .775rem; color: var(--text-muted); }

/* ===== SCROLL REVEAL ===== */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity .55s cubic-bezier(.4,0,.2,1), transform .55s cubic-bezier(.4,0,.2,1);
}
.reveal.visible { opacity: 1; transform: none; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-sidebar { flex-direction: row; }
  .hero-card { min-height: 200px; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card-featured { grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-search { display: none; }
  .nav-menu-toggle { display: flex; }
  .hero-sidebar { flex-direction: column; }
  .deals-section { padding: 2rem 1.25rem; }
  .promo-banner { flex-direction: column; align-items: flex-start; }
  .testimonials-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 480px) {
  main { padding: 0 1rem; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== FOCUS VISIBLE ===== */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 3px;
}

