function renderEditorial() {
  const grid = document.getElementById('editorial-grid');
  const featured = EDITORIAL.find(e => e.featured);
  const rest = EDITORIAL.filter(e => !e.featured);

  const bgClasses = ['ed-sm-1', 'ed-sm-2'];
  const shapeClasses = ['ed-sm-1-s', 'ed-sm-2-s'];

  grid.innerHTML = `
