}

function renderCategories() {
  const grid = document.getElementById('categories-grid');
  grid.innerHTML = CATEGORIES.map(c => `
    <button class="category-pill reveal" aria-label="Browse ${c.name}">
      <span class="category-icon" aria-hidden="true">${c.icon}</span>
      <span class="category-name">${c.name}</span>
    </button>`).join('');
}

/* ===== Cart & Wishlist interactions ===== */
function showToast(name) {
  const toast = document.getElementById('cart-toast');
  toast.querySelector('.cart-toast-text').textContent = 'Added to Cart';
  toast.querySelector('.cart-toast-sub').textContent = name;
  toast.classList.add('show');
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => toast.classList.remove('show'), 2800);
}

function updateCartBadge() {
  const badge = document.getElementById('cart-badge');
  badge.textContent = cartCount;
  badge.style.display = cartCount > 0 ? 'flex' : 'none';
}

document.addEventListener('click', e => {
  // Add to cart — products
  const cartBtn = e.target.closest('[data-cart]');
  if (cartBtn) {
    const id = parseInt(cartBtn.dataset.cart);
    const product = PRODUCTS.find(p => p.id === id);
    if (product) {
      cart.push(product);
      cartCount++;
      updateCartBadge();
      showToast(product.name);
      cartBtn.setAttribute('aria-label', `${product.name} added to cart`);
    }
    return;
  }

  // Add to cart — deals
  const dealBtn = e.target.closest('[data-cart-deal]');
  if (dealBtn) {
    const id = parseInt(dealBtn.dataset.cartDeal);
    const deal = DEALS.find(d => d.id === id);
    if (deal) {
      cartCount++;
      updateCartBadge();
      showToast(deal.name);
    }
    return;
  }

  // Wishlist toggle
  const wishBtn = e.target.closest('[data-wishlist]');
  if (wishBtn) {
    const id = parseInt(wishBtn.dataset.wishlist);
    if (wishlist.has(id)) {
      wishlist.delete(id);
      wishBtn.classList.remove('active');
      wishBtn.querySelector('svg').setAttribute('fill', 'none');
      wishBtn.setAttribute('aria-label', `Add to wishlist: ${PRODUCTS.find(p => p.id === id).name}`);
    } else {
      wishlist.add(id);
      wishBtn.classList.add('active');
      wishBtn.querySelector('svg').setAttribute('fill', 'currentColor');
      wishBtn.setAttribute('aria-label', `Remove from wishlist: ${PRODUCTS.find(p => p.id === id).name}`);
    }
    return;
  }
});

/* ===== Countdown timers ===== */
const timers = DEALS.map(d => ({ id: d.id, h: d.hours, m: d.mins, s: d.secs }));

function tickTimers() {
  timers.forEach(t => {
    t.s--;
    if (t.s < 0) { t.s = 59; t.m--; }
    if (t.m < 0) { t.m = 59; t.h--; }
    if (t.h < 0) { t.h = 0; t.m = 0; t.s = 0; }
    const hEl = document.querySelector(`[data-deal-h="${t.id}"]`);
    const mEl = document.querySelector(`[data-deal-m="${t.id}"]`);
    const sEl = document.querySelector(`[data-deal-s="${t.id}"]`);
    if (hEl) hEl.textContent = String(t.h).padStart(2, '0');
    if (mEl) mEl.textContent = String(t.m).padStart(2, '0');
    if (sEl) sEl.textContent = String(t.s).padStart(2, '0');
  });
}

/* ===== Scroll reveal ===== */
function initReveal() {
  const io = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        io.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08 });
  document.querySelectorAll('.reveal').forEach(el => io.observe(el));
}

/* ===== Mobile nav toggle ===== */
function initMobileNav() {
  const toggle = document.getElementById('nav-menu-toggle');
  const links = document.getElementById('nav-links');
  if (!toggle || !links) return;

  toggle.addEventListener('click', () => {
    const open = links.classList.toggle('nav-links-open');
    toggle.setAttribute('aria-expanded', open);
    links.style.display = open ? 'flex' : '';
  });
}

/* ===== Init ===== */
function init() {
  renderProducts();
  renderDeals();
  renderEditorial();
  renderCategories();
  updateCartBadge();
  initReveal();
  initMobileNav();
  setInterval(tickTimers, 1000);
}

document.addEventListener('DOMContentLoaded', init);
