+          <button class="product-wishlist${wishlist.has(p.id) ? ' active' : ''}"
+            aria-label="${wishlist.has(p.id) ? 'Remove from' : 'Add to'} wishlist: ${p.name}"
+            data-wishlist="${p.id}">
+            <svg width="16" height="16" viewBox="0 0 24 24" fill="${wishlist.has(p.id) ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
